#!/usr/bin/env node
// One-time cleanup for the "Print Job Stuck" alert rows generated by the
// checkStaleJobs() sweep that has been removed from server.js. Leaves every
// other "queue" category alert alone (Print queue blocked, Printer Offline)
// - only rows whose title matches that generator's exact pattern are touched.
//
// Works against whichever store this backend actually uses: the kiosk_alerts
// table in Postgres/RDS if DATABASE_URL (or POSTGRES_URL) is set, otherwise
// the local data.json file (same lookup rds-store.js/server.js use).
//
// Usage (run from the backend/ directory on the server):
//   node scripts/purge-print-job-stuck-alerts.js            # dry run - reports what would be deleted
//   node scripts/purge-print-job-stuck-alerts.js --confirm  # actually deletes

const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "..");
const TITLE_REGEX_JS = / - Print Job Stuck \(/;
const TITLE_REGEX_SQL = " - Print Job Stuck \\(";
const CONFIRM = process.argv.includes("--confirm");

function loadEnvFile(envPath) {
  if (!fs.existsSync(envPath)) return;
  for (const line of fs.readFileSync(envPath, "utf8").split("\n")) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith("#")) continue;
    const eq = trimmed.indexOf("=");
    if (eq === -1) continue;
    const key = trimmed.slice(0, eq).trim();
    let value = trimmed.slice(eq + 1).trim();
    if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith("'") && value.endsWith("'"))) {
      value = value.slice(1, -1);
    }
    if (!(key in process.env)) process.env[key] = value;
  }
}

loadEnvFile(path.join(ROOT, ".env"));

const DATABASE_URL = process.env.DATABASE_URL || process.env.POSTGRES_URL || "";

async function purgeFromPostgres() {
  const { Pool } = require("pg");
  const DATABASE_SSL = /^(true|1|require)$/i.test(process.env.DATABASE_SSL || process.env.PGSSLMODE || "");
  const pool = new Pool({
    connectionString: DATABASE_URL,
    ssl: DATABASE_SSL ? { rejectUnauthorized: false } : undefined
  });

  try {
    const preview = await pool.query(
      `SELECT alert_id, data->>'title' AS title, data->>'status' AS status, data->>'createdAt' AS created_at
       FROM kiosk_alerts
       WHERE data->>'title' ~ $1
       ORDER BY updated_at ASC`,
      [TITLE_REGEX_SQL]
    );

    console.log(`Found ${preview.rowCount} "Print Job Stuck" alert row(s) in kiosk_alerts.`);
    if (preview.rowCount) {
      console.log("Examples:");
      preview.rows.slice(0, 5).forEach((row) => console.log(`  ${row.created_at}  [${row.status}]  ${row.title}`));
    }

    if (!CONFIRM) {
      console.log("\nDry run only - no rows deleted. Re-run with --confirm to actually delete them.");
      return;
    }

    if (!preview.rowCount) {
      console.log("Nothing to delete.");
      return;
    }

    const result = await pool.query(`DELETE FROM kiosk_alerts WHERE data->>'title' ~ $1`, [TITLE_REGEX_SQL]);
    console.log(`Deleted ${result.rowCount} row(s) from kiosk_alerts.`);
  } finally {
    await pool.end();
  }
}

function purgeFromJsonFile() {
  const dataPath = process.env.DATA_PATH ? path.resolve(process.env.DATA_PATH) : path.join(ROOT, "data.json");
  if (!fs.existsSync(dataPath)) {
    console.error(`No DATABASE_URL is set and no data.json found at ${dataPath} - nothing to clean up.`);
    process.exitCode = 1;
    return;
  }

  const raw = JSON.parse(fs.readFileSync(dataPath, "utf8"));
  const alertLogs = Array.isArray(raw.alertLogs) ? raw.alertLogs : [];
  const matches = alertLogs.filter((alert) => TITLE_REGEX_JS.test(alert?.title || ""));

  console.log(`Found ${matches.length} "Print Job Stuck" alert row(s) in ${dataPath}.`);
  if (matches.length) {
    console.log("Examples:");
    matches.slice(0, 5).forEach((alert) => console.log(`  ${alert.createdAt}  [${alert.status}]  ${alert.title}`));
  }

  if (!CONFIRM) {
    console.log("\nDry run only - no rows deleted. Re-run with --confirm to actually delete them.");
    return;
  }

  if (!matches.length) {
    console.log("Nothing to delete.");
    return;
  }

  raw.alertLogs = alertLogs.filter((alert) => !TITLE_REGEX_JS.test(alert?.title || ""));

  const backupPath = `${dataPath}.bak-${Date.now()}`;
  fs.copyFileSync(dataPath, backupPath);

  const tempPath = `${dataPath}.${process.pid}.tmp`;
  fs.writeFileSync(tempPath, JSON.stringify(raw, null, 2));
  fs.renameSync(tempPath, dataPath);

  console.log(`Deleted ${matches.length} row(s). Backup of the original file saved at ${backupPath}.`);
  console.log("Restart the backend service for it to pick up the change (it only reads data.json at startup).");
}

async function main() {
  if (DATABASE_URL) {
    console.log("DATABASE_URL is set - cleaning up the kiosk_alerts table in Postgres.");
    await purgeFromPostgres();
  } else {
    console.log("No DATABASE_URL set - cleaning up the local data.json file instead.");
    purgeFromJsonFile();
  }
}

main().catch((error) => {
  console.error("Cleanup failed:", error.message);
  process.exitCode = 1;
});
